const COMPANY_LOGO =
  "data:image/jpeg;base64,";

const SIGNATURE_IMAGE =
  "data:image/jpeg;base64,"
  
import { PDFDocument, StandardFonts, rgb } from "pdf-lib";
const sanitizeText = (text) => {
  if (!text) return "";

  return text
    .replace(/\t/g, " ")        // remove tabs
    .replace(/\r/g, " ")        // remove carriage returns
    .replace(/\n/g, " ")        // optional: flatten newlines
    .replace(/[^\x00-\xFF]/g, ""); // remove unsupported chars
};
const safe = (text) => sanitizeText(text);

export async function generatePDF(form, sections, mode = "full") {
  const pdfDoc = await PDFDocument.create();

  const font = await pdfDoc.embedFont(StandardFonts.Helvetica);
  const boldFont = await pdfDoc.embedFont(StandardFonts.HelveticaBold);

  let page = pdfDoc.addPage([595, 842]);

  const margin = 40;
  let y = 800;

  // ================= LOGO (FIRST PAGE ONLY) =================

// remove Base64 prefix for pdf-lib
    // ================= LOGO (FIRST PAGE ONLY) =================
  const logoBase64 = COMPANY_LOGO.replace(
    /^data:image\/jpeg;base64,/,
    ""
  );

  const logoImage = await pdfDoc.embedJpg(logoBase64);

  page.drawImage(logoImage, {
    x: page.getWidth() - margin - 80,
    y: 770,
    width: 80,
    height: 40,
  });

  // ================= PAGE BREAK =================
  const SIGNATURE_SPACE = 80;
  const newPageCheck = () => {
    if (y < 60 + SIGNATURE_SPACE) {
      page = pdfDoc.addPage([595, 842]);
      y = 800;
    }
  };

  // ================= TEXT WRAPPING =================
  const wrapText = (text, maxWidth, font, size) => {
    const words = String(text).split(" ");
    const lines = [];
    let currentLine = "";

    for (let word of words) {
      const testLine = currentLine ? currentLine + " " + word : word;

      const width = font.widthOfTextAtSize(safe(testLine), size);

      if (width > maxWidth) {
        if (currentLine) lines.push(currentLine);
        currentLine = word;
      } else {
        currentLine = testLine;
      }
    }

    if (currentLine) lines.push(currentLine);

    return lines;
  };

  // ================= BASIC TEXT =================
  const drawText = (text, size = 10, bold = false) => {
    newPageCheck();

    page.drawText(safe(text), {
      x: margin,
      y,
      size,
      font: bold ? boldFont : font,
      color: rgb(0, 0, 0),
    });

    y -= size + 5;
  };

  // ================= SUBTITLE =================
  const drawSubtitle = (text) => {
    newPageCheck();

    const size = 11;

    page.drawText(safe(text), {
      x: margin + 10,
      y,
      size,
      font: boldFont,
      color: rgb(0, 0, 0),
    });

    const width = boldFont.widthOfTextAtSize(text, size);

    page.drawLine({
      start: { x: margin + 10, y: y - 2 },
      end: { x: margin + 10 + width, y: y - 2 },
      thickness: 0.8,
      color: rgb(0, 0, 0),
    });

    y -= 16;
  };

  // ================= QUESTION ROW =================
  const drawRow = (q, a) => {
    const left = margin;
    const questionWidth = 500;
    const answerX = 560;

    const qLines = wrapText(q, questionWidth, font, 10);

    for (let i = 0; i < qLines.length; i++) {
      newPageCheck();

      page.drawText(safe(qLines[i]), {
        x: left,
        y,
        size: 10,
        font,
        color: rgb(0, 0, 0),
      });

      if (i === 0) {
        page.drawText(safe(a), {
          x: answerX,
          y,
          size: 10,
          font: boldFont,
          color: rgb(0, 0, 0),
        });
      }

      y -= 14;
    }
  };

  // ================= TITLE =================
  drawText(
    "Torremolinos & ILO188 Outfit Guidance Report",
    16,
    true
  );

  y -= 10;

  // ================= VESSEL DETAILS =================
  drawText("VESSEL DETAILS", 14, true);

  const vesselFields = [
    ["Name of Vessel", form.vesselName],
    ["Call Sign", form.callsign],
    ["Date", form.date],
  ];

  vesselFields.forEach(([label, value]) => {
    drawText(`${label}: ${value || ""}`);
  });

  y -= 10;

  // ================= SECTIONS =================
  sections.forEach((section) => {
    drawText(section.title, 12, true);

    section.subsections.forEach((sub) => {
      drawSubtitle(sub.subtitle);

      sub.questions.forEach((q) => {
        const rawAnswer = form[q.id];

        const answer =
          rawAnswer === undefined ||
          rawAnswer === null ||
          rawAnswer === ""
            ? "NOT ANSWERED"
            : String(rawAnswer);

        // ================= ONLY FIX (DEFICIENCIES LOGIC) =================
        if (mode === "deficiencies") {
          const isNo =
            String(answer).trim().toLowerCase() === "no";

          if (isNo) {
            drawRow(safe(q.label), answer);

            const deficiencyText = `Required Action: ${
              q.deficiency || "N/A"
            }`;

            const wrapped = wrapText(
              deficiencyText,
              500,
              boldFont,
              10
            );

            wrapped.forEach((line) => {
              newPageCheck();

              page.drawText(line, {
                x: margin + 10,
                y,
                size: 10,
                font: boldFont,
                color: rgb(0, 0, 0),
              });

              y -= 14;
            });

            y -= 5;
          }

          return;
        }

        // FULL MODE
        drawRow(q.label, answer);
      });

      y -= 10;
    });

    y -= 10;
  });

// ================= SIGNATURE (LAST PAGE ONLY) =================
const signatureBase64 = SIGNATURE_IMAGE.replace(
  /^data:image\/jpeg;base64,/,
  ""
);

const signatureImage = await pdfDoc.embedJpg(signatureBase64);

// if there isn't enough space left, create one final page
if (y < 120) {
  page = pdfDoc.addPage([595, 842]);
  y = 800;
}

// draw signature on actual final page
page.drawText("Signed by Surveyor:", {
  x: margin,
  y: y - 20,
  size: 10,
  font: boldFont,
  color: rgb(0, 0, 0),
});

page.drawImage(signatureImage, {
  x: margin,
  y: y - 80,
  width: 120,
  height: 50,
});

// ================= PAGE NUMBERS =================
const allPages = pdfDoc.getPages();
const totalPages = allPages.length;

allPages.forEach((currentPage, index) => {
  currentPage.drawText(
    `Page ${index + 1} of ${totalPages}`,
    {
      x: currentPage.getWidth() / 2 - 30,
      y: 15,
      size: 10,
      font,
      color: rgb(0, 0, 0),
    }
  );
});

return await pdfDoc.save();
}